import os
import re
from collections import Counter
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter, column_index_from_string
from openpyxl.utils.cell import coordinate_from_string

IN_PATH = '/root/data/workbook.xlsx'
OUT_PATH = '/root/output/result.xlsx'

TASK_SHEET = 'Task'
DATA_SHEET = 'Data'

TASK_PRINT_RANGE = ('D', 10, 'L', 50)  # D10:L50


def is_year(v):
    if v is None or v == '':
        return False
    if isinstance(v, (int, float)):
        return int(v) in (2018, 2019, 2020, 2021, 2022)
    if isinstance(v, str):
        s = v.strip()
        if s.isdigit():
            return int(s) in (2018, 2019, 2020, 2021, 2022)
    return False


def normalize_year(v):
    if isinstance(v, (int, float)):
        return int(v)
    if isinstance(v, str) and v.strip().isdigit():
        return int(v.strip())
    raise ValueError(v)


def main():
    wb = load_workbook(IN_PATH, data_only=False)
    if TASK_SHEET not in wb.sheetnames or DATA_SHEET not in wb.sheetnames:
        raise RuntimeError(f"Expected sheets {TASK_SHEET} and {DATA_SHEET}, found: {wb.sheetnames}")

    ws_task = wb[TASK_SHEET]
    ws_data = wb[DATA_SHEET]

    # 2) Print Task rows 10-50, cols D-L
    print('=== INSPECTION: Task!D10:L50 (values) ===')
    for r in range(10, 51):
        row_vals = []
        for c in range(column_index_from_string('D'), column_index_from_string('L') + 1):
            v = ws_task.cell(row=r, column=c).value
            row_vals.append('' if v is None else str(v))
        print(f"R{r:02d}:\t" + "\t".join(row_vals))

    # 3) Print Data rows 21-38 (plus scan a wider range to locate headers)
    print('\n=== INSPECTION: Data!rows 19-38 (A:Z, values) ===')
    for r in range(19, 39):
        vals = []
        for c in range(1, 27):  # A-Z
            v = ws_data.cell(row=r, column=c).value
            vals.append('' if v is None else str(v))
        print(f"R{r:02d}:\t" + "\t".join(vals))

    # Identify where years live on Data sheet
    year_hits = []  # (row, col, year)
    for r in range(1, min(ws_data.max_row, 200) + 1):
        for c in range(1, min(ws_data.max_column, 100) + 1):
            v = ws_data.cell(row=r, column=c).value
            if is_year(v):
                year_hits.append((r, c, normalize_year(v)))

    if not year_hits:
        raise RuntimeError('Could not find any year headers (2018-2022) on Data sheet.')

    # Pick the header row with the most year hits (tie -> smallest row)
    cnt = Counter([r for r, _, _ in year_hits])
    header_row = sorted(cnt.items(), key=lambda x: (-x[1], x[0]))[0][0]

    header_year_cols = sorted({c for r, c, _ in year_hits if r == header_row})
    if len(header_year_cols) < 3:
        raise RuntimeError(f"Found too few year headers on candidate header row {header_row}: cols={header_year_cols}")

    first_year_col = min(header_year_cols)
    last_year_col = max(header_year_cols)

    # Determine the series code column by matching Task series codes against Data rows 21:38
    task_series_codes = []
    for r in list(range(12, 18)) + list(range(19, 25)) + list(range(26, 32)):
        v = ws_task[f"D{r}"].value
        if isinstance(v, str) and v.strip():
            task_series_codes.append(v.strip())

    if not task_series_codes:
        raise RuntimeError('No series codes found in Task!D12:D31.')

    # Search data rows 21-38 for these codes and infer the column
    matches = []
    for r in range(21, 39):
        for c in range(1, ws_data.max_column + 1):
            v = ws_data.cell(row=r, column=c).value
            if isinstance(v, str) and v.strip() in task_series_codes:
                matches.append((r, c, v.strip()))

    if not matches:
        # Helpful dump: show any *_REN_GEN style strings we can find
        pattern = re.compile(r'_[A-Z]+_')
        found = []
        for r in range(21, 39):
            for c in range(1, ws_data.max_column + 1):
                v = ws_data.cell(row=r, column=c).value
                if isinstance(v, str) and 'REN' in v or 'GRID' in v or 'BASE' in v:
                    found.append((r, c, str(v)))
        raise RuntimeError(f"No Task series codes found in Data rows 21-38. Sample strings: {found[:15]}")

    series_col_counts = Counter([c for _, c, _ in matches])
    series_col = series_col_counts.most_common(1)[0][0]

    # Build ranges
    first_year_col_letter = get_column_letter(first_year_col)
    last_year_col_letter = get_column_letter(last_year_col)
    series_col_letter = get_column_letter(series_col)

    index_range = f"Data!${first_year_col_letter}$21:${last_year_col_letter}$38"
    match_row_range = f"Data!${series_col_letter}$21:${series_col_letter}$38"
    match_col_range = f"Data!${first_year_col_letter}${header_row}:${last_year_col_letter}${header_row}"

    print('\n=== DERIVED LOOKUP RANGES (Data sheet) ===')
    print('Year header row:', header_row)
    print('Year columns:', f"{first_year_col_letter}:{last_year_col_letter}")
    print('Series code column:', series_col_letter)
    print('INDEX range:', index_range)
    print('MATCH row :', match_row_range)
    print('MATCH col :', match_col_range)

    # Step 1  Lookup formulas in blocks
    def fill_index_match_block(top_left: str, bottom_right: str):
        (c1, r1) = coordinate_from_string(top_left)
        (c2, r2) = coordinate_from_string(bottom_right)
        c1i = column_index_from_string(c1)
        c2i = column_index_from_string(c2)
        for r in range(r1, r2 + 1):
            for c in range(c1i, c2i + 1):
                col_letter = get_column_letter(c)
                formula = (
                    f"=INDEX({index_range}, "
                    f"MATCH($D{r}, {match_row_range}, 0), "
                    f"MATCH({col_letter}$10, {match_col_range}, 0))"
                )
                ws_task.cell(row=r, column=c).value = formula

    fill_index_match_block('H12', 'L17')
    fill_index_match_block('H19', 'L24')
    fill_index_match_block('H26', 'L31')

    # Step 2  Net Renewable Balance in H35:L40 (rows correspond to campuses)
    for i in range(6):
        net_r = 35 + i
        gen_r = 12 + i
        grid_r = 19 + i
        base_r = 26 + i
        for c in range(column_index_from_string('H'), column_index_from_string('L') + 1):
            col = get_column_letter(c)
            ws_task.cell(row=net_r, column=c).value = f"=({col}{gen_r}-{col}{grid_r})/{col}{base_r}*100"

    # Step 2 continued  Summary stats in H42:L47 matched to labels
    label_cols = ['C', 'D', 'E', 'F', 'G']

    def detect_label(row: int) -> str:
        for col in label_cols:
            v = ws_task[f"{col}{row}"].value
            if isinstance(v, str) and v.strip():
                return v.strip()
        v = ws_task[f"D{row}"].value
        return '' if v is None else str(v)

    stat_rows = list(range(42, 48))
    labels = {r: detect_label(r) for r in stat_rows}

    print('\n=== DETECTED STAT LABELS (Task rows 42-47) ===')
    for r in stat_rows:
        print(f"Row {r}: {labels[r]!r}")

    def stat_formula_for_label(col_letter: str, label: str):
        lab = (label or '').upper()
        rng = f"{col_letter}$35:{col_letter}$40"
        if 'MIN' in lab:
            return f"=MIN({rng})"
        if 'MAX' in lab:
            return f"=MAX({rng})"
        if 'MEDIAN' in lab:
            return f"=MEDIAN({rng})"
        if 'AVERAGE' in lab or 'MEAN' in lab:
            return f"=AVERAGE({rng})"
        if '25' in lab or 'Q1' in lab or '1ST' in lab or 'P25' in lab:
            return f"=PERCENTILE({rng},0.25)"
        if '75' in lab or 'Q3' in lab or '3RD' in lab or 'P75' in lab:
            return f"=PERCENTILE({rng},0.75)"
        return None

    for r in stat_rows:
        label = labels[r]
        for c in range(column_index_from_string('H'), column_index_from_string('L') + 1):
            col = get_column_letter(c)
            f = stat_formula_for_label(col, label)
            if f is not None:
                ws_task.cell(row=r, column=c).value = f

    # Step 3  Weighted mean in H50:L50
    for c in range(column_index_from_string('H'), column_index_from_string('L') + 1):
        col = get_column_letter(c)
        ws_task.cell(row=50, column=c).value = f"=SUMPRODUCT({col}35:{col}40,{col}26:{col}31)/SUM({col}26:{col}31)"

    # Save output
    os.makedirs(os.path.dirname(OUT_PATH), exist_ok=True)
    wb.save(OUT_PATH)
    print('\n=== SAVED ===')
    print('Saved to:', OUT_PATH)

    # Reopen and spot-check that formulas were written (not values)
    wb2 = load_workbook(OUT_PATH, data_only=False)
    ws2 = wb2[TASK_SHEET]

    print('\n=== SPOT-CHECK FORMULAS (Task, data_only=False) ===')
    for addr in ['H12', 'L17', 'H19', 'L24', 'H26', 'L31', 'H35', 'L40', 'H42', 'H46', 'H47', 'H50', 'L50']:
        print(f"{addr}: {ws2[addr].value}")

    print('\nSheets in saved workbook:', wb2.sheetnames)

    # Verify no bad percentile variants in our edited areas
    problem_hits = []
    areas = [(12, 17), (19, 24), (26, 31), (35, 40), (42, 47), (50, 50)]
    for r1, r2 in areas:
        for r in range(r1, r2 + 1):
            for c in range(column_index_from_string('H'), column_index_from_string('L') + 1):
                v = ws2.cell(row=r, column=c).value
                if isinstance(v, str) and v.startswith('='):
                    up = v.upper()
                    if 'PERCENTILE.INC' in up or 'PERCENTILE.EXC' in up:
                        problem_hits.append((f"{get_column_letter(c)}{r}", 'bad_percentile_variant', v))
                    if '#REF!' in up or '#NAME?' in up:
                        problem_hits.append((f"{get_column_letter(c)}{r}", 'embedded_error_token', v))

    print('\nProblematic formula TEXT hits:', len(problem_hits))
    for hit in problem_hits[:50]:
        print('  ', hit)

    # data_only=True spot check for cached error strings (may be None if never calculated)
    wb3 = load_workbook(OUT_PATH, data_only=True)
    ws3 = wb3[TASK_SHEET]
    print('\n=== SPOT-CHECK CACHED VALUES (Task, data_only=True) ===')
    for addr in ['H12', 'H42', 'H46', 'H47', 'H50']:
        v = ws3[addr].value
        print(f"{addr}: {v}")
        if isinstance(v, str) and v.startswith('#'):
            print('  WARNING: cached error value')


if __name__ == '__main__':
    main()
